/**
 * Demo seed: a "Knockd Demo" team with ~6 weeks of past sessions around Byron, so the web map
 * opens with history (fading paths, lead-rate colours, leads with notes) for the demo.
 *
 * Sessions are generated by walking crews along real streets (the simulated-crew routes) at a
 * realistic pace, then run through the real end-of-session processing and uploaded to the team.
 * Lead chances follow census income per block (plus randomness), so the map shows a pattern.
 * Deterministic: the same seed gives the same history.
 *
 * Usage (from apps/server):
 *   pnpm seed:demo              create the team if missing, add sessions, print an invite link
 *   pnpm seed:demo --reset      delete the demo team and its sessions, then regenerate
 *   pnpm seed:demo --promote    make everyone who joined via the invite an editor
 *   pnpm seed:demo --team <id> [--sessions 8]
 *                               add made-up sessions to an existing team, uploaded by its owner
 *                               (different each run, so running it again adds more)
 */
import { randomBytes } from "node:crypto";
import { and, eq, sql } from "drizzle-orm";
import { distanceM, HIGHLIGHT_COLOURS, type Grade, type SimPace } from "@knockd/shared";
import { db, pg } from "../src/db/client";
import { maps, sessionMembers, sessions, teamInvites, teamMembers, teams, teamSessions, users } from "../src/db/schema";
import { env } from "../src/env";
import { processSession } from "../src/jobs/process-session";
import { planRoutes, type Stop } from "../src/sim/routes";

const TEAM_NAME = "Knockd Demo";
const OWNER_SUB = "seed|knockd-demo";
const SESSIONS = 12;
const DAYS_BACK = 42;
const SHIFT_HOURS = 2.5;
const PACE: SimPace = "realistic";
const WALK_MS = 1.3;
const PING_EVERY_S = 5;
const BASE_LEAD_CHANCE = 0.05; // per door, before the block's receptiveness
const CREW = ["Tristan", "Jasmine", "Alex", "Sam", "Jordan", "Riley"];
const COLOURS = ["#E4572E", "#2E86AB", "#F2A541", "#7B2CBF", "#2A9D8F", "#D81E5B"];
const NOTES = [
  "loved our work",
  "old house, peeling paint",
  "wants a quote for the deck",
  "call after 6pm",
  "neighbour of a past customer",
  "don't knock, very bad",
];
/** Byron, where crews work. */
const BYRON = { minLat: 42.944, maxLat: 42.97, minLng: -81.37, maxLng: -81.325 };

const argv = process.argv.slice(2);
const args = new Set(argv);
const argValue = (name: string) => (argv.includes(name) ? argv[argv.indexOf(name) + 1] : undefined);

// Deterministic randomness (mulberry32), so re-running gives the same history.
let seed = 20261121;
function rand(): number {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const pick = <T>(list: T[]) => list[Math.floor(rand() * list.length)]!;
const between = (lo: number, hi: number) => lo + rand() * (hi - lo);

async function main() {
  // ---------- --team: made-up sessions for an existing team ----------
  const teamId = argValue("--team");
  if (teamId) {
    const [existing] = await db.select().from(teams).where(eq(teams.id, teamId));
    if (!existing) throw new Error(`No team with id ${teamId}`);
    const count = Number(argValue("--sessions") ?? 8);
    seed = Date.now() | 0; // a new history each run
    console.log(`Adding ${count} sessions to "${existing.name}"`);
    await addSessions(existing.id, existing.createdBy, count);
    await refreshAggregates();
    return;
  }

  // ---------- owner + team ----------
  await db.insert(users).values({ auth0Sub: OWNER_SUB, displayName: "Demo Owner" }).onConflictDoNothing();
  const [owner] = await db.select().from(users).where(eq(users.auth0Sub, OWNER_SUB));
  let [team] = await db
    .select()
    .from(teams)
    .where(and(eq(teams.name, TEAM_NAME), eq(teams.createdBy, owner!.id)));

  if (args.has("--promote")) {
    if (!team) throw new Error("No demo team yet. Run without --promote first.");
    const promoted = await db
      .update(teamMembers)
      .set({ role: "editor" })
      .where(and(eq(teamMembers.teamId, team.id), eq(teamMembers.role, "viewer")))
      .returning({ userId: teamMembers.userId });
    console.log(`✓ Promoted ${promoted.length} member(s) to editor`);
    return;
  }

  if (team && args.has("--reset")) {
    await db.execute(sql`
      DELETE FROM sessions WHERE id IN (SELECT session_id FROM team_sessions WHERE team_id = ${team.id})`);
    await db.delete(teams).where(eq(teams.id, team.id));
    team = undefined;
    console.log("✓ Deleted the old demo team and its sessions");
  }

  if (!team) {
    [team] = await db.insert(teams).values({ name: TEAM_NAME, createdBy: owner!.id }).returning();
    await db.insert(teamMembers).values({ teamId: team!.id, userId: owner!.id, role: "owner" });
    const byronBoundary = sql`ST_Multi(ST_MakeEnvelope(${BYRON.minLng}, ${BYRON.minLat}, ${BYRON.maxLng}, ${BYRON.maxLat}, 4326))`;
    await db.insert(maps).values([
      { teamId: team!.id, name: "World Map", createdBy: owner!.id },
      { teamId: team!.id, name: "Byron", boundary: byronBoundary, createdBy: owner!.id },
    ]);
    console.log(`✓ Created team "${TEAM_NAME}" with maps World Map and Byron`);

    await addSessions(team!.id, owner!.id, SESSIONS);

    // ---------- highlights & notes on never-worked blocks (what a boss would mark on the web) ----------
    const fresh = await db.execute<{ id: number }>(sql`
      SELECT b.id FROM blocks b
      WHERE b.house_count >= 10
        AND b.geom && ST_MakeEnvelope(${BYRON.minLng}, ${BYRON.minLat}, ${BYRON.maxLng}, ${BYRON.maxLat}, 4326)
        AND NOT EXISTS (SELECT 1 FROM session_block_stats s JOIN team_sessions ts ON ts.session_id = s.session_id
                        WHERE ts.team_id = ${team!.id} AND s.block_id = b.id)
      ORDER BY b.id LIMIT 3`);
    const [blockA, blockB, blockC] = fresh.map((b) => Number(b.id));
    // Two areas (a loose loop around a block) and one road (a street next to the third block).
    for (const [blockId, colour] of [
      [blockA, HIGHLIGHT_COLOURS[1]],
      [blockB, HIGHLIGHT_COLOURS[0]],
    ] as const)
      await db.execute(sql`
        INSERT INTO team_highlights (team_id, geom, colour, created_by)
        SELECT ${team!.id}, ST_ExteriorRing(ST_Buffer(geom::geography, 15)::geometry)::geometry, ${colour}, ${owner!.id}
        FROM blocks WHERE id = ${blockId}`);
    await db.execute(sql`
      UPDATE team_highlights SET geom = ST_MakePolygon(geom)
      WHERE team_id = ${team!.id} AND GeometryType(geom) = 'LINESTRING' AND ST_IsClosed(geom)`);
    await db.execute(sql`
      INSERT INTO team_highlights (team_id, geom, colour, created_by)
      SELECT ${team!.id}, s.geom, ${HIGHLIGHT_COLOURS[2]}, ${owner!.id}
      FROM houses h JOIN streets s ON s.id = h.street_id
      WHERE h.block_id = ${blockC} LIMIT 1`);
    const notes: [number | undefined, string][] = [
      [blockA, "Older houses, lots of peeling trim"],
      [blockB, "New owners moved in this summer"],
      [blockC, "Busy road, knock the side streets"],
    ];
    for (const [blockId, text] of notes)
      await db.execute(sql`
        INSERT INTO team_notes (team_id, location, text, created_by)
        SELECT ${team!.id}, ST_PointOnSurface(geom), ${text}, ${owner!.id} FROM blocks WHERE id = ${blockId}`);
    console.log("✓ Added 3 highlights and 3 notes on never-worked blocks");

    await refreshAggregates();
  } else {
    console.log(`✓ Team "${TEAM_NAME}" already exists (use --reset to regenerate)`);
  }

  // ---------- invite ----------
  const token = randomBytes(18).toString("base64url");
  const expiresAt = new Date(Date.now() + 7 * 86_400_000);
  await db.insert(teamInvites).values({ token, teamId: team!.id, createdBy: owner!.id, expiresAt });
  console.log(`\nTeam ID: ${team!.id}`);
  console.log(`Invite (7 days): ${env.INVITE_BASE_URL}/${token}`);
  console.log(`  Accept with your login token: POST /v1/invites/${token}/accept`);
  console.log("  Then run `pnpm seed:demo --promote` to make everyone who joined an editor.");
}

/** Raw pings older than the aggregates' refresh window would otherwise never be summarised. */
async function refreshAggregates() {
  for (const view of ["member_activity_1m", "leads_hourly", "knock_rate_hourly"])
    await pg.unsafe(`CALL refresh_continuous_aggregate('${view}', NULL, NULL)`);
  console.log("✓ Refreshed continuous aggregates");
}

/**
 * Makes up `count` past sessions around Byron, spread over the last 6 weeks, runs each
 * through the real processing and uploads it to the team as `uploaderId`.
 */
async function addSessions(teamId: string, uploaderId: string, count: number) {
  // ---------- houses → block → receptiveness (from census income) ----------
  const houseRows = await db.execute<{
    id: number;
    block_id: number;
    income: number | null;
    lat: number;
    lng: number;
  }>(sql`
    SELECT h.id, h.block_id, ST_Y(h.centroid) AS lat, ST_X(h.centroid) AS lng,
           (SELECT ca.median_household_income FROM census_areas ca WHERE ST_Contains(ca.geom, h.centroid) LIMIT 1) AS income
    FROM houses h
    WHERE h.block_id IS NOT NULL
      AND h.centroid && ST_MakeEnvelope(${BYRON.minLng - 0.01}, ${BYRON.minLat - 0.01}, ${BYRON.maxLng + 0.01}, ${BYRON.maxLat + 0.01}, 4326)`);
  const blockOf = new Map<number, number>();
  const receptiveness = new Map<number, number>();
  for (const h of houseRows) {
    const block = Number(h.block_id);
    blockOf.set(Number(h.id), block);
    if (!receptiveness.has(block)) {
      const incomeFactor = Math.min(1.8, Math.max(0.5, (h.income ?? 84_000) / 84_000));
      receptiveness.set(block, incomeFactor * between(0.3, 1.7));
    }
  }

  // ---------- sessions ----------
  const days = Array.from({ length: count }, (_, i) => Math.round(2 + (i * (DAYS_BACK - 2)) / Math.max(1, count - 1)));
  for (const [i, daysAgo] of days.entries()) {
    // Centre each shift on a real house inside Byron, so it's always in a residential area.
    const inByron = houseRows.filter(
      (h) => h.lat > BYRON.minLat && h.lat < BYRON.maxLat && h.lng > BYRON.minLng && h.lng < BYRON.maxLng,
    );
    const { lat, lng } = pick(inByron);
    const centre = { lat, lng };
    const start = new Date();
    start.setUTCDate(start.getUTCDate() - daysAgo);
    start.setUTCHours(22, 0, 0, 0); // 5 pm in London, ON (EST)
    const crew = [...CREW].sort(() => rand() - 0.5).slice(0, rand() < 0.5 ? 3 : 4);

    const [session] = await db
      .insert(sessions)
      .values({
        joinCode: randomBytes(4).toString("hex").slice(0, 6).toUpperCase(),
        status: "ended",
        startedAt: start,
        plannedArea: sql`ST_Buffer(ST_SetSRID(ST_MakePoint(${centre.lng}, ${centre.lat}), 4326)::geography, 350)::geometry(Polygon, 4326)`,
      })
      .returning({ id: sessions.id });
    const sessionId = session!.id;
    const members = await db
      .insert(sessionMembers)
      .values(crew.map((name, j) => ({ sessionId, displayName: name, colour: COLOURS[j]!, joinedAt: start })))
      .returning({ id: sessionMembers.id });
    await db.update(sessions).set({ createdByMemberId: members[0]!.id }).where(eq(sessions.id, sessionId));

    const routes = await planRoutes(
      sessionId,
      members.map((m) => m.id),
      PACE,
      null,
    );

    let pingCount = 0;
    let leadCount = 0;
    let lastT = start.getTime();
    for (const m of members) {
      const { pings, leads } = walkShift(
        routes.get(m.id) ?? [],
        start.getTime() + between(0, 300_000),
        blockOf,
        receptiveness,
      );
      for (let k = 0; k < pings.length; k += 2000) {
        await db.execute(sql`
          INSERT INTO pings (time, session_id, member_id, client_id, location, accuracy_m)
          SELECT to_timestamp((x->>'t')::double precision / 1000), ${sessionId}, ${m.id}, gen_random_uuid(),
                 ST_SetSRID(ST_MakePoint((x->>'lng')::float, (x->>'lat')::float), 4326), (x->>'acc')::real
          FROM jsonb_array_elements(${JSON.stringify(pings.slice(k, k + 2000))}::jsonb) x`);
      }
      if (leads.length)
        await db.execute(sql`
          INSERT INTO leads (id, session_id, member_id, house_id, grade, note, created_at, updated_at)
          SELECT gen_random_uuid(), ${sessionId}, ${m.id}, (x->>'houseId')::bigint, (x->>'grade')::lead_grade,
                 x->>'note', to_timestamp((x->>'t')::double precision / 1000), to_timestamp((x->>'t')::double precision / 1000)
          FROM jsonb_array_elements(${JSON.stringify(leads)}::jsonb) x`);
      pingCount += pings.length;
      leadCount += leads.length;
      lastT = Math.max(lastT, pings.at(-1)?.t ?? lastT);
    }
    await db
      .update(sessions)
      .set({ endedAt: new Date(lastT) })
      .where(eq(sessions.id, sessionId));
    await processSession(sessionId);
    await db
      .insert(teamSessions)
      .values({ teamId: teamId, sessionId, uploadedBy: uploaderId, uploadedAt: new Date(lastT) });
    console.log(
      `  ${String(i + 1).padStart(2)}/${count}  ${daysAgo} days ago  ${crew.join(", ")}  ${pingCount} pings, ${leadCount} leads`,
    );
  }
}

/** Walks a member's route at a realistic pace, producing pings and the odd lead. */
function walkShift(route: Stop[], startMs: number, blockOf: Map<number, number>, receptiveness: Map<number, number>) {
  const pings: { t: number; lat: number; lng: number; acc: number }[] = [];
  const leads: { t: number; houseId: number; grade: Grade; note: string | null }[] = [];
  const endMs = startMs + SHIFT_HOURS * 3_600_000;
  const used = new Set<number>();
  let t = startMs;
  let here = route[0];
  if (!here) return { pings, leads };

  const ping = (lat: number, lng: number) => {
    const j = () => (rand() * 2 - 1) * 3; // ±3 m of GPS wobble
    pings.push({
      t,
      lat: lat + j() / 111_320,
      lng: lng + j() / (111_320 * Math.cos((lat * Math.PI) / 180)),
      acc: Math.round(between(4, 10)),
    });
  };

  for (const stop of route) {
    if (t > endMs) break;
    // Walk to the stop.
    const d = distanceM(here, stop);
    const steps = Math.max(1, Math.round(d / (WALK_MS * PING_EVERY_S)));
    for (let s = 1; s <= steps; s++) {
      t += PING_EVERY_S * 1000;
      ping(here.lat + ((stop.lat - here.lat) * s) / steps, here.lng + ((stop.lng - here.lng) * s) / steps);
    }
    here = stop;
    // Stand at the door.
    for (let w = 0; w < stop.stopS; w += PING_EVERY_S) {
      t += PING_EVERY_S * 1000;
      ping(stop.lat, stop.lng);
    }
    const houseId = stop.houseIds.find((id) => !used.has(id));
    if (stop.stopS > 0 && houseId !== undefined) {
      used.add(houseId);
      const chance = BASE_LEAD_CHANCE * (receptiveness.get(blockOf.get(houseId) ?? -1) ?? 1);
      if (rand() < chance) {
        const r = rand();
        const grade: Grade = r < 0.25 ? "A" : r < 0.6 ? "B" : "C";
        leads.push({ t, houseId, grade, note: grade !== "C" && rand() < 0.35 ? pick(NOTES) : null });
      }
    }
  }
  return { pings, leads };
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => pg.end());
